package org.freecad.mobilelab;
import org.json.*;import java.util.*;
/** Typed local DAG. Numbers, lists and points are separate from exact CAD geometry. */
final class ParametricGraph {
 static int[] lastOutputs=new int[0];
 static final String[] KINDS={"Number","Add","Subtract","Multiply","Divide","Sin","Cos","Range","Series","List item","Point","Point list","Point series","Curve point","Surface point","Polyline","NURBS curve","Circle","Rectangle","Box","Ring","Sphere","Cylinder","Torus","Bezel","Prongs","Patch","Extrude","Move","Rotate","Scale","Loft","Sweep","Pipe","Union","Cut","Intersect","Linear array","Polar array","Curve array"};
 static String[] ports(String k){switch(k){case "Number":return new String[0];case "Add":case "Subtract":case "Multiply":case "Divide":return new String[]{"A","B"};case "Sin":case "Cos":return new String[]{"Angle (degrees)"};case "Range":return new String[]{"Start","End","Count"};case "Series":return new String[]{"Start","Step","Count"};case "List item":return new String[]{"Number list","Index (zero-based)"};case "Point":return new String[]{"X","Y","Z"};case "Point list":return new String[]{"Point A","Point B"};case "Point series":return new String[]{"Origin point","Step vector","Count"};case "Curve point":return new String[]{"Single curve","Parameter fraction"};case "Surface point":return new String[]{"NURBS patch","U fraction","V fraction"};case "Polyline":case "NURBS curve":return new String[]{"Point list"};case "Circle":case "Sphere":return new String[]{"Radius"};case "Rectangle":return new String[]{"Width","Depth"};case "Cylinder":return new String[]{"Radius","Height"};case "Torus":return new String[]{"Major radius","Tube radius"};case "Box":return new String[]{"Width","Depth","Height"};case "Ring":return new String[]{"Inner diameter","Wall","Band width"};case "Bezel":return new String[]{"Stone diameter","Wall","Height","Seat depth"};case "Prongs":return new String[]{"Stone diameter","Wall","Height","Seat depth","Count","Prong diameter"};case "Patch":return new String[]{"Width","Depth","Bulge"};case "Extrude":return new String[]{"Closed profile","Height"};case "Move":return new String[]{"Geometry","X offset","Y offset","Z offset"};case "Rotate":return new String[]{"Geometry","X degrees","Y degrees","Z degrees"};case "Scale":return new String[]{"Geometry","Factor"};case "Loft":return new String[]{"Lower profile","Upper profile"};case "Sweep":return new String[]{"Profile","Rail"};case "Pipe":return new String[]{"Rail","Radius"};case "Union":case "Cut":case "Intersect":return new String[]{"Body A","Body B"};case "Linear array":return new String[]{"Geometry","Copies","X step","Y step","Z step"};case "Polar array":return new String[]{"Geometry","Copies","Angle"};case "Curve array":return new String[]{"Geometry","Rail","Count","XY tangent orientation (0/1)"};default:throw new IllegalArgumentException("Unknown graph component");}}
 static String outputType(String k){if(Arrays.asList("Number","Add","Subtract","Multiply","Divide","Sin","Cos","List item").contains(k))return "number";if(k.equals("Range")||k.equals("Series"))return "numbers";if(Arrays.asList("Point","Curve point","Surface point").contains(k))return "point";if(k.equals("Point list")||k.equals("Point series"))return "points";ports(k);return "geometry";}
 static String inputType(String k,int port){if(k.equals("List item")&&port==0)return "numbers";if(k.equals("Point list")||k.equals("Point series")&&port<2)return "point";if(k.equals("Polyline")||k.equals("NURBS curve"))return "points";if(Arrays.asList("Move","Rotate","Scale","Extrude","Pipe","Linear array","Polar array","Curve point","Surface point").contains(k)&&port==0||Arrays.asList("Loft","Sweep","Union","Cut","Intersect").contains(k)||k.equals("Curve array")&&port<2)return "geometry";return "number";}
 static boolean numeric(String k){return outputType(k).equals("number");}static boolean geometryPort(String k,int p){return inputType(k,p).equals("geometry");}
 static boolean compatible(String k,int p,String source){return inputType(k,p).equals(outputType(source));}
 static String example(){return "{\"version\":1,\"nodes\":[{\"id\":1,\"kind\":\"Number\",\"value\":18,\"inputs\":[]},{\"id\":2,\"kind\":\"Number\",\"value\":1.6,\"inputs\":[]},{\"id\":3,\"kind\":\"Number\",\"value\":3,\"inputs\":[]},{\"id\":4,\"kind\":\"Ring\",\"inputs\":[1,2,3]}],\"outputs\":[4]}";}
 static final class Value{final String type;final double n;final int geometry;final double[] data;Value(double x){type="number";n=x;geometry=0;data=null;}Value(int id){type="geometry";geometry=id;n=0;data=null;}Value(String t,double[] p){type=t;data=p;n=0;geometry=0;}}
 private final Map<Integer,JSONObject> nodes=new LinkedHashMap<>();private final Map<Integer,Value> values=new HashMap<>();private final ArrayList<Integer> made=new ArrayList<>();
 private ParametricGraph(String json)throws Exception{if(json==null||json.length()>128000)throw new IllegalArgumentException("Graph is too large");JSONObject root=new JSONObject(json);if(root.optInt("version",1)!=1)throw new IllegalArgumentException("Unsupported graph version");JSONArray list=root.getJSONArray("nodes");if(list.length()<1||list.length()>80)throw new IllegalArgumentException("Graph needs 1 to 80 components");for(int i=0;i<list.length();i++){JSONObject node=list.getJSONObject(i);int id=node.getInt("id");String kind=node.getString("kind");if(id<1||id>100000||nodes.put(id,node)!=null)throw new IllegalArgumentException("Duplicate or invalid node ID");if(node.getJSONArray("inputs").length()!=ports(kind).length)throw new IllegalArgumentException("Wrong component connections: "+kind);if(node.optString("group").length()>80)throw new IllegalArgumentException("Group label too long");if(kind.equals("Number")&&(!Double.isFinite(node.getDouble("value"))||Math.abs(node.getDouble("value"))>1000000))throw new IllegalArgumentException("Number must be finite and within +/-1,000,000");}}
 static void validate(String json)throws Exception{ParametricGraph g=new ParametricGraph(json);Set<Integer> done=new HashSet<>();for(int id:g.nodes.keySet())g.validateNode(id,new HashSet<Integer>(),done);JSONArray outputs=new JSONObject(json).optJSONArray("outputs");if(outputs==null||outputs.length()<1||outputs.length()>80)throw new IllegalArgumentException("Choose geometry outputs");Set<Integer> used=new HashSet<>();for(int i=0;i<outputs.length();i++){int id=outputs.getInt(i);JSONObject n=g.nodes.get(id);if(n==null||!used.add(id)||!outputType(n.getString("kind")).equals("geometry"))throw new IllegalArgumentException("Graph output must be distinct geometry");}}
 private void validateNode(int id,Set<Integer> active,Set<Integer> done)throws Exception{if(done.contains(id))return;if(!active.add(id))throw new IllegalArgumentException("Graph connections form a cycle");JSONObject n=nodes.get(id);if(n==null)throw new IllegalArgumentException("Missing component "+id);String kind=n.getString("kind");JSONArray in=n.getJSONArray("inputs");for(int p=0;p<in.length();p++){JSONObject source=nodes.get(in.getInt(p));if(source==null)throw new IllegalArgumentException("Connect every input on "+kind);if(!compatible(kind,p,source.getString("kind")))throw new IllegalArgumentException("Input "+ports(kind)[p]+" needs "+inputType(kind,p));validateNode(in.getInt(p),active,done);}active.remove(id);done.add(id);}
 static int whole(double n,int low,int high){if(n!=Math.floor(n)||n<low||n>high)throw new IllegalArgumentException("Count/index must be an integer from "+low+" to "+high);return (int)n;}
 private Value node(int id)throws Exception{if(values.containsKey(id))return values.get(id);JSONObject n=nodes.get(id);String k=n.getString("kind");JSONArray in=n.getJSONArray("inputs");Value[] a=new Value[in.length()];for(int i=0;i<a.length;i++)a[i]=node(in.getInt(i));Value r;
  switch(k){case "Number":r=new Value(n.getDouble("value"));break;case "Add":r=new Value(a[0].n+a[1].n);break;case "Subtract":r=new Value(a[0].n-a[1].n);break;case "Multiply":r=new Value(a[0].n*a[1].n);break;case "Divide":if(a[1].n==0)throw new IllegalArgumentException("Division by zero");r=new Value(a[0].n/a[1].n);break;case "Sin":r=new Value(Math.sin(Math.toRadians(a[0].n)));break;case "Cos":r=new Value(Math.cos(Math.toRadians(a[0].n)));break;
  case "Range":case "Series":{int count=whole(a[2].n,1,1000);double[] p=new double[count];for(int i=0;i<count;i++)p[i]=a[0].n+(k.equals("Series")?a[1].n*i:(a[1].n-a[0].n)*(count==1?0:(double)i/(count-1)));r=new Value("numbers",p);break;}
  case "List item":r=new Value(a[0].data[whole(a[1].n,0,a[0].data.length-1)]);break;case "Point":r=new Value("point",new double[]{a[0].n,a[1].n,a[2].n});break;case "Point list":r=new Value("points",new double[]{a[0].data[0],a[0].data[1],a[0].data[2],a[1].data[0],a[1].data[1],a[1].data[2]});break;
  case "Point series":{int count=whole(a[2].n,2,64);double[] p=new double[count*3];for(int i=0;i<count;i++)for(int j=0;j<3;j++)p[i*3+j]=a[0].data[j]+a[1].data[j]*i;r=new Value("points",p);break;}
  case "Curve point":r=new Value("point",NativeCad.samplePoint(a[0].geometry,new double[]{a[1].n}));break;case "Surface point":r=new Value("point",NativeCad.samplePoint(a[0].geometry,new double[]{a[1].n,a[2].n}));break;
  case "Polyline":case "NURBS curve":{double[] p=new double[a[0].data.length/3*4];for(int i=0;i<p.length/4;i++){System.arraycopy(a[0].data,i*3,p,i*4,3);p[i*4+3]=1;}r=new Value(NativeCad.curve(k,p,false,0));break;}
  case "Circle":case "Sphere":r=new Value(NativeCad.create(k,new double[]{a[0].n}));break;case "Rectangle":case "Cylinder":case "Torus":r=new Value(NativeCad.create(k,new double[]{a[0].n,a[1].n}));break;case "Box":case "Ring":case "Patch":r=new Value(NativeCad.create(k.equals("Patch")?"NURBS patch":k,new double[]{a[0].n,a[1].n,a[2].n}));break;case "Bezel":case "Prongs":{double[] p=new double[a.length];for(int i=0;i<p.length;i++)p[i]=a[i].n;r=new Value(NativeCad.create(k.equals("Bezel")?"Bezel setting":"Prong setting",p));break;}
  case "Extrude":r=new Value(NativeCad.model("Extrude solid",new int[]{a[0].geometry},new double[]{0,0,a[1].n}));break;case "Loft":case "Sweep":r=new Value(NativeCad.model(k+" solid",new int[]{a[0].geometry,a[1].geometry},k.equals("Loft")?new double[]{0}:new double[0]));break;case "Pipe":r=new Value(NativeCad.model("Pipe along curve",new int[]{a[0].geometry},new double[]{a[1].n}));break;case "Union":case "Cut":case "Intersect":r=new Value(NativeCad.operation(k,a[0].geometry,a[1].geometry,0));break;
  case "Move":r=new Value(NativeCad.duplicate(a[0].geometry,a[1].n,a[2].n,a[3].n));break;case "Rotate":case "Scale":{int copy=NativeCad.duplicate(a[0].geometry,0,0,0);if(k.equals("Scale"))NativeCad.scale(copy,a[1].n);else NativeCad.rotate(copy,a[1].n,a[2].n,a[3].n);r=new Value(copy);break;}
  case "Linear array":case "Polar array":r=new Value(NativeCad.array(a[0].geometry,k,whole(a[1].n,2,100),k.equals("Linear array")?new double[]{a[2].n,a[3].n,a[4].n,0}:new double[]{0,0,0,a[2].n}));break;case "Curve array":r=new Value(NativeCad.arrayCurve(a[0].geometry,a[1].geometry,whole(a[2].n,2,100),whole(a[3].n,0,1)==1));break;default:throw new IllegalArgumentException("Unknown component");}
  if(r.type.equals("number")&&(!Double.isFinite(r.n)||Math.abs(r.n)>1000000))throw new IllegalArgumentException("Graph math exceeds +/-1,000,000");if(r.data!=null)for(double d:r.data)if(!Double.isFinite(d)||Math.abs(d)>1000000)throw new IllegalArgumentException("List/point values out of range");if(r.type.equals("geometry")){made.add(r.geometry);NativeCad.markGraphOwned(r.geometry,true);NativeCad.visible(r.geometry,false);}values.put(id,r);return r;
 }
 static int evaluate(String json,int[] previous)throws Exception{validate(json);Set<Integer> prior=new HashSet<>();for(int id:previous)prior.add(id);JSONArray current=new JSONArray(NativeCad.objects());for(int i=0;i<current.length();i++){JSONObject o=current.getJSONObject(i);if(o.optBoolean("graphOwned")||prior.contains(o.getInt("id")))FeatureModel.remove(o.getInt("id"));}ParametricGraph g=new ParametricGraph(json);JSONArray outputs=new JSONObject(json).getJSONArray("outputs");int selected=0;for(int i=0;i<outputs.length();i++){selected=g.node(outputs.getInt(i)).geometry;NativeCad.visible(selected,true);}lastOutputs=new int[g.made.size()];for(int i=0;i<lastOutputs.length;i++)lastOutputs[i]=g.made.get(i);return selected;}
 static Value inspect(String json,int node)throws Exception{validate(json);return new ParametricGraph(json).node(node);}
 static String variant(String json,int numberId,double value)throws Exception{JSONObject g=new JSONObject(json);JSONArray a=g.getJSONArray("nodes");boolean found=false;for(int i=0;i<a.length();i++){JSONObject n=a.getJSONObject(i);if(n.getInt("id")==numberId&&n.getString("kind").equals("Number")){n.put("value",value);found=true;}}if(!found)throw new IllegalArgumentException("Choose a Number node");g.put("version",1);validate(g.toString());return g.toString();}
}
